/// <summary>
/// MPJ_34596_TransferOrderFinalisation, Data contract class for transfer shipping  generation service
/// </summary>
[DataContractAttribute]
class METTransferShipingListGenerationContract
{
    container            transferOrderList;
    MetShipmentId        metShipmentId   ;
    InventLocationId     fromWarehouseLocation,toWarehouseLocation;

}

Method.Source:
    /// <summary>
    /// parm method for transfer order list container which contains transfer order 
    /// </summary>
    /// <param name = "_transferOrderList">transfer order list</param>
    /// <returns>transfer order list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmTransferOrderList(container _transferOrderList = transferOrderList)
    {
        transferOrderList = _transferOrderList;

        return transferOrderList;
    }

    public MetShipmentId parmMetShipmentId(MetShipmentId _metShipmentId = metShipmentId)
    {
        metShipmentId = _metShipmentId;

        return metShipmentId;
    }

    public InventLocationId parmFromWarehouse(InventLocationId _fromWarehouseLocation = fromWarehouseLocation)
    {
        fromWarehouseLocation = _fromWarehouseLocation;

        return fromWarehouseLocation;
    }

    public InventLocationId parmToWarehouse(InventLocationId _toWarehouseLocation = toWarehouseLocation)
    {
        toWarehouseLocation = _toWarehouseLocation;

        return toWarehouseLocation;
    }
